mapper.select:
SELECT c.*, u.unit_name as unitName, u.unit_principal_name as unitPrincipalName, u.unit_principal_phone as unitPrincipalPhone, u.social_credit_code as socialCreditCode, ctd.name as cylinderTypes, ccl.cylinder_qty as cylinderQty FROM contract c LEFT JOIN unit u ON c.unit_id = u.unit_id LEFT JOIN contract_cylinder_line ccl ON ccl.contract_id = c.contract_id LEFT JOIN cylinder_type_dict ctd ON ctd.cylinder_type_id = ccl.cylinder_type_id
AND u.unit_name LIKE CONCAT('%', #{unitName}, '%')
AND ( c.contract_no LIKE CONCAT('%', #{keyword}, '%') OR u.unit_name LIKE CONCAT('%', #{keyword}, '%') OR c.party_a_name LIKE CONCAT('%', #{keyword}, '%') OR c.party_b_name LIKE CONCAT('%', #{keyword}, '%') )
AND c.contract_status = #{contractStatus}
AND c.start_date >= #{startDateBegin}
AND c.start_date <= #{startDateEnd}
AND c.end_date >= #{endDateBegin}
AND c.end_date <= #{endDateEnd}
ORDER BY c.created_at DESC
